MY=[['希腊 myein 关闭 → mystēs 入秘仪者','可能联想到闭口保密或闭眼；具体连接未定']]
MYSTERY=MY+[['希腊 mystērion → 拉丁 mysterium → 古法语 mistere → 英语 mystery','秘密仪式、奥秘 → 不知道原因的事']]
MYSTIC=MY+[['希腊 mystikos → 拉丁 mysticus；古法语 mistique → 英语 mystic','与秘仪相关 → 神秘体验、神秘主义相关']]
MYSTIFY=MY+[['希腊 mystikos → 拉丁 mysticus → 法语 mystique → mystifier → 英语 mystify','神秘的 → 使事情难解、让人困惑']]
W += [
E('mystery','英 /ˈmɪstri/；美 /ˈmɪstəri/','谜；奥秘；推理故事','有结果或线索摆在眼前，却还不知道背后的答案。','经法语、拉丁语接希腊 mystērion 秘仪、奥秘，与 mystēs 入秘仪者和 myein 关闭相连；闭口或闭眼的具体联想未定。',MYSTERY,'solve a mystery 是解开谜团；remain a mystery 是仍无法解释。a murder mystery 既可指一桩未解凶案，也常指推理小说或影视作品。','solve a mystery；remain a mystery；a mystery novel；the mystery of。','secret 是被保密的信息，可能有人清楚答案；mystery 强调原因或答案尚不清楚。古旧手艺义 mystery 另接 ministerium 服务，不是本支。',('The missing key remained a mystery until we moved the sofa.','直到我们挪开沙发，钥匙失踪之谜才解开。'),('She reads a mystery on every long train journey.','每次坐长途火车，她都会读一本推理小说。'),sources=['https://www.etymonline.com/word/mystery','https://en.wiktionary.org/wiki/mystery#English']),
E('mysterious','英 /mɪˈstɪəriəs/；美 /mɪˈstɪriəs/','神秘的；难以解释的','知道发生了什么，却看不清原因、来历或真正身份。','取 mystery 所接的 mysterium 词干，加 -ous，表示带有奥秘、难以解释。',MY+[['希腊 mystērion → 拉丁 mysterium；加 -ous → 英语 mysterious','奥秘 → 难以解释、带神秘感的']],'a mysterious noise 是来源不明的声响；a mysterious smile 可能是故意不说破的微笑。它并不自动表示超自然。','a mysterious disappearance；mysterious circumstances；a mysterious stranger。','unknown 只说不知道；mysterious 往往还带困惑、好奇或难以解释的感觉。',('A mysterious light appeared in the empty building.','空楼里出现了一道来历不明的光。'),('She gave me a mysterious smile and changed the subject.','她神秘地笑了笑，换了个话题。'),sources=['https://www.etymonline.com/word/mysterious','https://www.oxfordlearnersdictionaries.com/definition/english/mysterious']),
E('mysteriously','英 /mɪˈstɪəriəsli/；美 /mɪˈstɪriəsli/','神秘地；不知何故地','事情发生得让人摸不着原因，或者一个人故意留着答案不说。','mysterious + -ly；把神秘、难解变成事件发生或行为表现的方式。',MY+[['希腊 mystērion → 拉丁 mysterium → mysterious → mysteriously','奥秘 → 神秘的 → 不知何故地、神秘地']],'mysteriously vanish 是不知何故消失；smile mysteriously 是意味不明地微笑。副词未说明原因，不能据此断定有人蓄意隐瞒。','mysteriously disappear；mysteriously absent；smile mysteriously。','secretly 明确说秘密进行；mysteriously 说旁人解释不清，两者不等同。',('The file had mysteriously disappeared from the shared folder.','文件不知何故从共享文件夹里消失了。'),('He smiled mysteriously when I mentioned the surprise.','我提到那份惊喜时，他神秘地笑了。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/mysteriously','https://en.wiktionary.org/wiki/mysteriously#English']),
E('mystic','/ˈmɪstɪk/','神秘主义者；神秘体验相关的','强调通过内在体验、沉思等去接近神圣或终极实在的人；作形容词也可带神秘色彩。','经法语或拉丁语接希腊 mystikos；与 mystery 同源，但不是直接截掉 mystery 的词尾。',MYSTIC+[['英语 mystic 的人物义','神秘体验相关的 → 追求或表达这类体验的人']],'a medieval mystic 是中世纪神秘主义者；mystic poetry 指带相关精神体验的诗歌。现代形容词常用 mystical，名词 mystic 更常指人。','a religious mystic；a medieval mystic；mystic poetry。','magician 是魔术师或故事中的巫师；mystic 不等于会表演魔术的人。mysterious 只说难解。',('The course examines the writings of a medieval mystic.','课程研究一位中世纪神秘主义者的著作。'),('The poem is filled with mystic imagery.','这首诗充满神秘主义意象。'),sources=['https://www.etymonline.com/word/mystic','https://en.wiktionary.org/wiki/mystic#English']),
E('mystical','/ˈmɪstɪkəl/','神秘主义的；具有神秘、超凡感的','不像普通知识推理，更像一种难以言说的精神体验；也能形容仿佛超出日常的气氛。','mystic + -al；英语形容词扩展，不是 mystery 直接变 -ical。',MYSTIC+[['英语 mystic + -al → mystical','神秘的、象征性的 → 神秘体验相关的']],'a mystical experience 是神秘精神体验；a mystical atmosphere 可描写艺术或自然带来的超凡感。描写这种感觉不等于证明有超自然力量。','a mystical experience；mystical traditions；a mystical quality。','mysterious 常是尚未解释的；mystical 更容易涉及精神、宗教或超凡体验。',('The music gives the scene an almost mystical quality.','音乐让这一幕带上近乎超凡的神秘感。'),('The book compares mystical traditions from several cultures.','这本书比较了几种文化中的神秘主义传统。'),sources=['https://www.etymonline.com/word/mystical','https://www.oxfordlearnersdictionaries.com/definition/english/mystical']),
E('mysticism','/ˈmɪstɪsɪzəm/','神秘主义；重视直接精神体验的思想或实践','认为某些深层或神圣真理可以通过内在体验接近，而不只靠日常推理和感官知识。','mystic + -ism；-ism 把相关体验、思想或实践作为一个体系来讲。',MYSTIC+[['英语 mystic + -ism → mysticism','神秘体验相关 → 神秘主义思想和实践']],'religious mysticism 指宗教中的神秘主义传统；也可讨论诗歌里这种倾向。不同传统内容不同，这个总称不代表一套统一教义。','religious mysticism；the study of mysticism；elements of mysticism。','mystery 是谜或奥秘；mysticism 是思想、体验或实践传统，不是谜题很多。',('Her research focuses on mysticism in medieval literature.','她研究中世纪文学中的神秘主义。'),('The lecture distinguished mysticism from stage magic.','讲座区分了神秘主义与舞台魔术。'),sources=['https://www.etymonline.com/word/mysticism','https://www.oxfordlearnersdictionaries.com/definition/english/mysticism']),
E('mystify','/ˈmɪstɪfaɪ/','使困惑；使难以理解','像给事情蒙上一层雾，让人怎么想都想不通。','借法语 mystifier；它由 mystique 神秘的与 -fier 使成为不规则构成。现代可用 myst- + -ify 辅助记忆。',MYSTIFY,'a decision mystifies me 是一个决定让我想不通。可以是无意造成困惑，也可以是故意把事情说得玄乎，并不要求出现真正秘密。','mystify somebody；be mystified by；mystify the public。','confuse 泛指弄混、困惑；mystify 更突出无法看出原因或解释。demystify 则是把事情讲明白。',('The sudden change of plan mystified everyone.','计划突然改变，让所有人都摸不着头脑。'),('Technical language can mystify readers who are new to the subject.','专业术语可能让刚接触这个领域的读者困惑。'),sources=['https://www.etymonline.com/word/mystify','https://www.oxfordlearnersdictionaries.com/definition/english/mystify']),
E('mystified','/ˈmɪstɪfaɪd/','困惑的；摸不着头脑的','人站在谜团前，已经看见发生的事，却找不到合理解释。','mystify 的过去分词；y 改 i 加 -ed，常作形容词描述受困惑影响的人。',MYSTIFY+[['英语 mystify → mystified','使困惑 → 感到困惑的']],'be mystified by a result 是对结果感到困惑；remain mystified 表示仍想不通。它说理解受阻，不是人本身很神秘。','be mystified by；look mystified；remain mystified。','mystified 是感到困惑，mystifying 是令人困惑。a mystified reader 与 a mystifying sentence 的角色相反。',('I was mystified by the error message.','那条错误提示让我摸不着头脑。'),('She looked mystified when we started laughing.','我们笑起来时，她一脸困惑。'),sources=['https://www.etymonline.com/word/mystified','https://www.oxfordlearnersdictionaries.com/definition/english/mystify']),
E('mystifying','/ˈmɪstɪfaɪɪŋ/','令人困惑的；难以解释的','事情本身让人想不通，把周围的人变成满头问号。','mystify + -ing；保留 y，分词形容词表示造成困惑。',MYSTIFY+[['英语 mystify + -ing → mystifying','使困惑 → 让人想不通的']],'a mystifying decision 是难以理解的决定；mystifying behaviour 是原因不明的行为。通常比 merely surprising 多一层无法解释。','a mystifying decision；a mystifying result；utterly mystifying。','mystified 讲人的感受；mystifying 讲造成感受的事。mysterious 还可有吸引人探索的意味。',('The instructions contain a mystifying reference to a missing diagram.','说明里提到了一张不存在的图，让人困惑。'),('His refusal was mystifying to the rest of the team.','团队其他成员都想不通他为何拒绝。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/mystifying','https://en.wiktionary.org/wiki/mystifying#English']),
E('mystification','/ˌmɪstɪfɪˈkeɪʃən/','困惑；使事情神秘难懂的做法','可以是人心里的一团疑惑，也可以是把明白的事情故意说玄乎。','借法语 mystification，来自 mystifier；现代与 mystify 的 -fy / -fication 对应，但有独立法语名词借入线。',MY+[['希腊 mystikos → 拉丁 mysticus → 法语 mystique → mystifier → mystification → 英语 mystification','神秘的 → 使难解的行为；也指困惑状态']],'in mystification 是困惑地；the mystification of a simple process 可批评把简单过程弄得神秘复杂。比 confusion 更正式。','in mystification；a look of mystification；the mystification of。','mysticism 是思想或体验传统，mystification 是困惑或使其难解的行为，不能因为都含 myst- 就译成神秘主义。',('He shook his head in mystification.','他困惑地摇了摇头。'),('The article challenges the mystification of a fairly simple process.','文章反对把一个相当简单的过程故弄玄虚。'),sources=['https://www.etymonline.com/word/mystification','https://www.oxfordlearnersdictionaries.com/definition/english/mystification']),
E('demystify','/diːˈmɪstɪfaɪ/','把……讲明白；消除神秘感','把挡在外面的术语和迷雾拿掉，让人终于看见事情怎么运作。','de- 去除、逆转 + mystify；现代英语构词。',MYSTIFY+[['英语 de- + mystify → demystify','使难懂 → 消除难懂、神秘的感觉']],'demystify a topic 是把一个领域讲得容易懂。它不只是公布秘密，而是给出足够清楚的解释，让人不再觉得遥不可及。','demystify the process；demystify technology；help demystify。','simplify 可以真的删去步骤；demystify 可以保留全部过程，只是讲清楚。',('The workshop aims to demystify the application process.','工作坊旨在把申请流程讲清楚。'),('A few concrete examples helped demystify the software.','几个具体例子让这款软件不再显得难懂。'),sources=['https://www.etymonline.com/word/demystify','https://www.oxfordlearnersdictionaries.com/definition/english/demystify']),
E('demystification','/diːˌmɪstɪfɪˈkeɪʃən/','解释清楚；消除神秘感的过程','把看似只有专家懂的东西打开，让普通读者也能理解。','demystify 对应名词 demystification；也可看作 de- + mystification，现代两种拆法都帮助看清逆转关系。',MYSTIFY+[['英语 demystify → demystification','使容易懂 → 消除神秘感的过程']],'the demystification of science 是把科学原理讲明白；强调降低理解门槛，并不等于否认专业知识。','the demystification of；a process of demystification。','demystification 不必是揭穿骗局；一个完全真实的过程也可能需要清楚解释。',('The book contributes to the demystification of everyday technology.','这本书帮助读者理解日常技术，消除神秘感。'),('The teacher saw clear examples as a tool for demystification.','老师认为，清楚的例子能帮助学生弄懂原本觉得玄乎的内容。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/demystification','https://en.wiktionary.org/wiki/demystification#English']),
]
