DEFERRED={'miosis':'瞳孔缩小的专门医学术语，通用学习暂略。','myosis':'miosis 的另一拼写，专门医学术语暂略。','monohydrate':'专门化学计量词，先保留 hydrate 的基础概念。','hydrous':'较少用含水形容词，优先 hydrated 与 hydration。','hydrophobia':'较专门恐水、狂犬病相关旧术语，通用学习暂略。','hydatid':'寄生虫学专门词，暂略。','clepsydra':'古代水钟的较冷门名称，暂略。','hydathode':'专门植物组织名称，按用户冷词过滤偏好暂略。','hydatidosis':'专门寄生虫病名，暂略。','hydromancy':'较冷门占卜术名，暂略。','hydrophile':'较少用名词，优先常见形容词 hydrophilic。','hydrophily':'专门植物授粉方式名，暂略。','hydrostat':'较冷门专门装置或生物结构名，暂略。','polyhydric':'专门化学形容词，暂略。','hydrothermic':'少用专业形容词，暂略。','hydrozoa':'生物分类名称，暂不列通用词族。','hauriant':'纹章学专门形容词，暂略。','haustellate':'专门动物形态形容词，暂略。','haustellum':'昆虫口器专门名称，暂略。','haustorium':'专门植物、真菌结构名，暂略。','haustrum':'专门解剖结构名，暂略。','haurient':'罕用汲取相关形容词，暂略。'}
PIL_ROOT=dict(id='C1042',meaning='柱与小球的两条历史；堆积、药丸及同形分源',core='柱是垒起或撑住的结构；药丸则像一个小球。两幅画面分别记，不能见到 pil- 就把所有东西变成同一种形状。',image='拉丁 pila 柱 → pile 一堆、pillar 柱子；另一 pila 球 → pilula 小球 → pill。pile 的桩义另来自 pilum，绒面义另来自 pilus。',intro='拉丁表示柱与球的词恰好都写 pila，但更早联系并不确定。本页把相关常见词放在一起，同时保留来源界线。pillory 的示众枷义经古法语 pilori 而来，与柱的联系有争议，作为传统关联词阅读。',forms='pile 读 /paɪl/，pill 读 /pɪl/。pillar 不是 pill 加后缀的现代派生；piling 在堆积与打桩语境里接不同来源。stockpile 中的 pile 接堆积一支。',branches=[['柱、堆与储备','pile, pillar, pillared, piling, stockpile, stockpiling'],['球与药丸','pill, pillbox'],['传统关联、远源未定','pillory']],contrasts='pile 的一堆、桩、绒面有不同历史；pill 药丸与 pillar 柱不是现代简单加词尾。pillory 作动词多为公开抨击，不是普通批评的中性替换。',practice='用 pile 分别写纸堆、基础桩和地毯绒面；比较 pill 与 pillar 的发音；解释 a bitter pill to swallow 的画面。',words=list(ASSIGN['roots'][100]['family']),exclude={})
MY_ROOT=dict(id='C0778',meaning='关闭；奥秘、神秘体验与近视的不同分支',core='关闭的动作一边连到秘仪与保密，一边连到眯眼看东西；两条路后来形成很不一样的词。',image='希腊 myein 关闭 → mystēs 入秘仪者 → mystērion → mystery；mystikos → mystic、mystify。另由 myein + ōps 眼 → myopia。',intro='mystery 最早的核心与秘密仪式、宗教奥秘有关。关闭到底强调嘴唇保密还是眼睛的动作，具体联系并未完全确定，不能讲成唯一确定的故事。myopia 的眯眼命名线则另有眼的成分，并非 mystery 的派生。',forms='mystery、mystic 开头读 /mɪs-/，myopia、myopic 开头读 /maɪ-/。mysterious 重音后移；mystify 与 mystification 通过法语各自借入，demystify 是英语加 de-。',branches=[['看不清原因','mystery, mysterious, mysteriously'],['神秘精神体验','mystic, mystical, mysticism'],['使人困惑与困惑感','mystify, mystified, mystifying, mystification'],['把事情讲明白','demystify, demystification'],['眯眼与目光短浅〔共享〕','myopia, myopic']],contrasts='mysterious 常是原因难解，mystical 更靠近精神体验。mystified 是人困惑，mystifying 是事情让人困惑。英语 my 我的另属日耳曼代词，不能挂到希腊关闭词根。',practice='描述一个 mystery，再用 demystify 说明解释怎样解开它；比较 mysterious 与 mystical；用 mystified 和 mystifying 组成同一个场景。',words=list(ASSIGN['roots'][101]['family']),exclude={w:DEFERRED[w] for w in ASSIGN['roots'][101]['unmatched'] if w in DEFERRED})
HYDR_ROOT=dict(id='C0577',meaning='水；补水、液体作用与近代科学命名',core='想象水被补进来、抽出去、压过管道，或在天地间循环。不同动作把同一个水的成分带进不同领域。',image='希腊 hydōr → hydr-/hydro-；hydrate 补水 → dehydrate 去水、rehydrate 补回；hydraulic 液体传力；hydrology 研究水；hydroponics 营养液栽培。',intro='hydro- 常是水，但在 hydrochloric、hydrogenation 等化学词里也可能代表 hydrogen 氢。现代科学词多数由古典成分近代组合，不是古希腊已经有现成英语术语。词源说明命名来由，不能替代现代定义：液压可用油，碳水化合物也不是把碳混进水。',forms='hydrate、dehydrate、rehydrate 的英美常用重音不同；hydration 的重音在 -ation。hydrological 有独立的新拉丁构词线，英语记录早于常见 hydrology，别把所有 -ical 都排成现代名词后代。',branches=[['补水、失水与补回','hydrate, hydration, dehydrate, dehydrated, dehydration, rehydrate, rehydration'],['液压与取水装置','hydraulic, hydraulics, hydraulically, hydrant'],['水文研究和水圈','hydrology, hydrological, hydrologic, hydrologist, hydrosphere'],['水培与水电','hydroponics, hydroponic, hydroelectric, hydroelectricity, hydropower'],['化学与材料','carbohydrate, hydrogen, hydrochloric, hydrophobic, hydrophilic, hydrolysis, hydroxyl, hydrogenation'],['其他已讲支线','hydrostatic, hydrodynamics, dehydrogenase, hydra']],contrasts='hydraulic 用液体传力，pneumatic 用气体。hydrophobic 疏水不自动等于 waterproof 防漏。hydroponic 是栽培方式，hydroelectric 是发电方式。Hydra 的怪物与水螅名称要按上下文区分。',practice='用 hydrate、dehydrate、rehydrate 描述干食品吸水的前后；比较 hydraulic 与 hydrological；解释为什么水培仍需要营养物质。',words=list(dict.fromkeys([w for w in ASSIGN['roots'][102]['family'] if w not in DEFERRED]+['hydropower'])),exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][102]['family'])+ASSIGN['roots'][102]['unmatched'] if w in DEFERRED})
RAD_ROOT=dict(id='C1199',meaning='根、根本；根本改变与根除',core='枝叶可以修剪，根才是继续生长的基础；动到根，是根本改变，拔出根，是根除。',image='拉丁 radix / radicis 根 → radicalis → radical；e- 向外 + radix → eradicare → eradicate；radicem 经古英语成为 radish。',intro='radical 不只说政治激进。radical change 可以是产品设计的大变化，radix 可讲进位制基数，radish 则真是一种根菜。eradication 有拉丁名词的独立借入路线，不能一律按现代英语换词尾解释全部历史。',forms='radical 的 rad- 读 /ræd/，radix 常读 /ˈreɪdɪks/；radish 也读 /ræd-/。radicalization 美式中间音节常弱读，英式还常保留 /aɪ/。',branches=[['根本改变与变化方式','radical, radically'],['思想倾向与形成过程','radicalism, radicalize, radicalization'],['连根除去','eradicate, eradication, eradicated'],['学术根基与真正根菜','radix, radish']],contrasts='radicalism 是思想倾向，radicalization 是变化过程；reduce 是减少，eradicate 是彻底消除。radish 的 -ish 并不是有点……的现代形容词后缀。',practice='用 radical 描写一个不涉及政治的设计变化；比较问题被 reduced 与 eradicated；说明 radix 10 指什么。',words=list(ASSIGN['roots'][103]['family']),exclude={})
HAUR_ROOT=dict(id='C0522',meaning='汲取、抽出；耗尽与穷尽',core='从桶里一瓢瓢舀水，最后见底。人的力气会见底，储备会见底，清单里的可能项也可以被一项项查尽。',image='拉丁 haurire 汲水 → exhaurire 抽尽 → exhaustus → exhaust；exhausted 已耗尽；exhaustive 把所有部分查尽。',intro='这一组最值得区分的是精力被耗尽与内容被穷尽。exhausting 让人累，exhaustive 讲覆盖完整。排气名词 exhaust 则接向外抽排的动作，不是说车辆自己疲劳了。',forms='haust- 是拉丁分词中的形态，不能按现代英语 house 解释。exhaustion 里的 -tion 常读 /tʃən/；inexhaustible 的 in- 是否定。nonexhaustive 也常写成带连字符的形式，本页保留连写词头。',branches=[['用尽、排出','exhaust'],['疲劳的原因与结果','exhausting, exhausted, exhaustion'],['覆盖无遗漏','exhaustive, exhaustively, nonexhaustive'],['能否耗尽','exhaustible, inexhaustible']],contrasts='exhausted 是累坏的，exhausting 是让人累的，exhaustive 是详尽无遗漏的。exhaustible 是可能用完，exhausted 是已经用完；状态和可能性不同。',practice='用 exhausting 与 exhaustive 各描述一次调查；比较 exhausted resources 与 exhaustible resources；用 nonexhaustive 说明一份示例清单。',words=[w for w in ASSIGN['roots'][104]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][104]['family'])+ASSIGN['roots'][104]['unmatched'] if w in DEFERRED})
